export const askLLM = async (question, { lang = 'fr', user = null, data = [], adminSettings = {} } = {}) => {
  const openaiKey = process.env.REACT_APP_OPENAI_API_KEY || null;
  const geminiKey = process.env.REACT_APP_GEMINI_API_KEY || null;
  const locale = lang === 'en' ? 'en' : 'fr';
  const role = user && user.role ? user.role : 'user';
  const context = {
    locale,
    role,
    hasData: Array.isArray(data) && data.length > 0,
    operator: adminSettings?.operator || '',
    bankAccount: adminSettings?.bankAccount || '',
    phoneNumbers: adminSettings?.phoneNumbers || ''
  };
  const systemPrompt = locale === 'en'
    ? "You are Gtax Assistant. Focus on tax concepts, compliance, and app usage. Do not reveal admin/backend info or credentials. If a request is ambiguous, ask a brief clarifying question first, then give a clear, step-by-step answer with short bullets. Keep tone helpful and concise. Decline topics unrelated to taxes or the app."
    : "Tu es l'Assistant Gtax. Concentre-toi sur les concepts fiscaux, la conformité et l'utilisation de l'application. Ne révèle pas d'informations admin/backend ni d'identifiants. Si la question est ambiguë, pose une courte clarification, puis donne une réponse claire et structurée en points. Ton doit être utile et concis. Refuse les sujets non liés aux impôts ou à l'application.";
  const userPrompt = `${locale === 'en' ? 'Question' : 'Question'}: ${question}\n${locale === 'en' ? 'Context' : 'Contexte'}: ${JSON.stringify(context)}`;
  try {
    if (geminiKey) {
      const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${geminiKey}`;
      const body = {
        contents: [
          { role: "user", parts: [{ text: `${systemPrompt}\n\n${userPrompt}` }] }
        ]
      };
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });
      if (res.ok) {
        const json = await res.json();
        const text = json?.candidates?.[0]?.content?.parts?.[0]?.text || null;
        if (text) return text.trim();
      }
    }
    if (openaiKey) {
      const url = 'https://api.openai.com/v1/chat/completions';
      const body = {
        model: 'gpt-4o-mini',
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt }
        ],
        temperature: 0.3
      };
      const res = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${openaiKey}`
        },
        body: JSON.stringify(body)
      });
      if (res.ok) {
        const json = await res.json();
        const text = json?.choices?.[0]?.message?.content || null;
        if (text) return text.trim();
      }
    }
  } catch (e) {
    return null;
  }
  return null;
};
